437	\begin{lemma}[Preservation of the robustness error family]\label{lem:qld-extraction-error-form}
438		\lean{MIPStarRE.QPBT.deltaExtract_le_deltaQld}
439		\uses{def:admissible, lem:qld-unitary}
440		Let $C\geq1$, $a>1$, and $0<b<1$. Suppose that
441		\[
442			\delta_G=a(md)^a\bigl(\eps^b+q^{-b}+2^{-bmd}\bigr),
443			\qquad
444			\delta_P=C\left(\delta_G+\sqrt{\eps}+\frac{md}{q}\right),
445		\]
446		and set $\delta_{\mathrm{ext}}=C(\delta_P^{1/4}+md/q)$. There are constants
447		$a'\geq1$ and $0<b'<1$, depending only on $C,a,b$, such that, for every
448		admissible $(q,m,d)$ and every $0\leq\eps\leq1$,
449		\[
450			\delta_{\mathrm{ext}}
451			\leq a'(md)^{a'}\bigl(\eps^{b'}+q^{-b'}+2^{-b'md}\bigr).
452		\]
453	\end{lemma}
